//http://codeforces.com/problemset/problem/78/E
//Evacuation

#include <bits/stdc++.h>

using namespace std;

const int MAX_SIZE = 300;

enum Cell { EMPTY = -1, REACTION = -2, HAZARD = -3, SHELTER = EMPTY };

struct Link {
    int u, v, reverse, current, limit;
    Link() : u(0), v(0), reverse(0), current(0), limit(0) {}
    Link(int a, int b, int r, int c, int l) : u(a), v(b), reverse(r), current(c), limit(l) {}
    int spare() const { return limit - current; }
};

class FlowNetwork {
public:
    int V;
    vector<Link*>* adj;
    Link** par;
    vector<int> seen;

    FlowNetwork(int n) : V(n), adj(new vector<Link*>[n]), par(new Link*[n]), seen(n, 0) {}

    ~FlowNetwork() {
        for (int i = 0; i < V; ++i) {
            for (auto* e : adj[i]) delete e;
            adj[i].clear();
        }
        delete[] adj;
        delete[] par;
    }

    void link(int a, int b, int cap) {
        Link* f = new Link(a, b, (int)adj[b].size(), 0, cap);
        Link* r = new Link(b, a, (int)adj[a].size(), 0, 0);
        adj[a].push_back(f);
        adj[b].push_back(r);
    }

    void bidirect(int a, int b, int cap) {
        Link* f = new Link(a, b, (int)adj[b].size(), 0, cap);
        Link* r = new Link(b, a, (int)adj[a].size(), 0, cap);
        adj[a].push_back(f);
        adj[b].push_back(r);
    }

    bool explore(int src, int dst) {
        fill(seen.begin(), seen.end(), 0);
        fill(par, par + V, nullptr);
        queue<int> q;
        q.push(src);
        seen[src] = 1;

        while (!q.empty()) {
            int cur = q.front(); q.pop();
            if (cur == dst) return true;
            for (Link* e : adj[cur]) {
                if (!seen[e->v] && e->spare() > 0) {
                    seen[e->v] = 1;
                    par[e->v] = e;
                    q.push(e->v);
                }
            }
        }
        return false;
    }

    int augment(int src, int dst) {
        int flow = INT_MAX;
        for (int v = dst; v != src; v = par[v]->u)
            flow = min(flow, par[v]->spare());
        for (int v = dst; v != src; v = par[v]->u) {
            Link* e = par[v];
            e->current += flow;
            adj[e->v][e->reverse]->current -= flow;
        }
        return flow;
    }

    long long maxFlow(int s, int t) {
        long long total = 0;
        while (explore(s, t)) total += augment(s, t);
        return total;
    }
};

int layout[MAX_SIZE][MAX_SIZE], capacity[MAX_SIZE][MAX_SIZE], danger[61][MAX_SIZE][MAX_SIZE];

struct Pos {
    int r, c, val;
    Pos(int x, int y, int n) : r(x), c(y), val(n) {}
    bool inGrid(int sz) const {
        return r >= 0 && r < sz && c >= 0 && c < sz && layout[r][c] == EMPTY;
    }
};

bool inBounds(int x, int y, int sz) { return Pos(x, y, 0).inGrid(sz); }

inline bool operator==(const Pos& p1, const Pos& p2) {
    return p1.r == p2.r && p1.c == p2.c;
}

vector<Pos> candidates, exits;
const int dRow[4] = {-1, 0, 1, 0};
const int dCol[4] = {0, -1, 0, 1};

int classify(char c) {
    if (c >= '0' && c <= '9') return EMPTY;
    if (c == 'Y') return REACTION;
    if (c == 'Z') return HAZARD;
    return -1;
}

int digit(char c) { return c - '0'; }

int distance(Pos start, Pos end, int sz) {
    bitset<MAX_SIZE> seen[MAX_SIZE];
    queue<pair<int, Pos>> q;
    q.push({0, start});
    seen[start.r][start.c] = true;

    while (!q.empty()) {
        int t = q.front().first;
        Pos cur = q.front().second;
        q.pop();

        if (cur == end) return t;
        if (danger[t][cur.r][cur.c]) continue;

        for (int k = 0; k < 4; ++k) {
            Pos next(cur.r + dRow[k], cur.c + dCol[k], 0);
            if (next.inGrid(sz) && !seen[next.r][next.c] && !danger[t][next.r][next.c]) {
                q.push({t + 1, next});
                seen[next.r][next.c] = true;
            }
        }
    }
    return 999;
}

void contaminate(int x, int y, int limit, int sz) {
    danger[0][x][y] = 1;
    for (int t = 1; t <= limit; ++t) {
        for (int i = 0; i < sz; ++i) {
            for (int j = 0; j < sz; ++j) {
                if (danger[t-1][i][j]) {
                    danger[t][i][j] = 1;
                    for (int k = 0; k < 4; ++k) {
                        int ni = i + dRow[k], nj = j + dCol[k];
                        if (ni >= 0 && ni < sz && nj >= 0 && nj < sz && layout[ni][nj] == EMPTY)
                            danger[t][ni][nj] = 1;
                    }
                }
            }
        }
    }
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);

    char ch;
    Pos source{0, 0, 0};
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            if (classify(ch) == EMPTY && digit(ch)) {
                candidates.emplace_back(i, j, digit(ch));
            }
            layout[i][j] = classify(ch);
            if (layout[i][j] == HAZARD) source = Pos(i, j, 0);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            if (classify(ch) == SHELTER && digit(ch)) {
                exits.emplace_back(i, j, digit(ch));
                capacity[i][j] = digit(ch);
            }
        }
    }

    FlowNetwork* net = new FlowNetwork(MAX_SIZE);
    int terminal = MAX_SIZE - 1;

    for (size_t i = 0; i < candidates.size(); ++i)
        net->link(0, i*2 + 1, candidates[i].val);

    for (size_t i = 0; i < exits.size(); ++i)
        net->link(i*2 + 2, terminal, exits[i].val);

    contaminate(source.r, source.c, T, N);

    for (size_t i = 0; i < candidates.size(); ++i) {
        for (size_t j = 0; j < exits.size(); ++j) {
            int d = distance(candidates[i], exits[j], N);
            if (d <= T) net->link(i*2 + 1, j*2 + 2, 999);
        }
    }

    printf("%lld\n", net->maxFlow(0, terminal));
    delete net;
    return 0;
}
